package com.primehr.migration;
import org.flywaydb.core.Flyway;import org.flywaydb.core.api.MigrationVersion;import org.junit.jupiter.api.Test;import java.sql.DriverManager;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class PrimeHrV44ToV45UpgradeTest{@Test void populatedAwardCycleSurvivesEvaluationMigration()throws Exception{String db="primehr_v45_"+UUID.randomUUID().toString().replace("-","");String url="jdbc:h2:mem:"+db+";MODE=PostgreSQL;DB_CLOSE_DELAY=-1";Map<String,String> p=Map.of("primehrSchema","PUBLIC");Flyway initial=flyway(url,p,"44");initial.migrate();try{try(var c=DriverManager.getConnection(url,"sa","");var s=c.createStatement()){s.executeUpdate("INSERT INTO PUBLIC.rr_governance_policy(id,agency_id,code,normalized_code,created_by,created_at,updated_by,updated_at) VALUES('policy','A','PRAISE','PRAISE','test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");s.executeUpdate("INSERT INTO PUBLIC.rr_governance_policy_version(id,agency_id,policy_id,definition_version,title,legal_basis,policy_reference,committee_required,allows_individual_awards,allows_group_awards,allows_organization_awards,allows_monetary_incentives,allows_nonmonetary_incentives,requires_agency_head_approval,annual_report_required,status,effective_from,published_by,published_at,record_version,created_by,created_at,updated_by,updated_at) VALUES('policy-v1','A','policy',1,'PRAISE','CSC MC','Resolution',TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,'PUBLISHED',DATE '2026-01-01','test',CURRENT_TIMESTAMP,0,'test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");s.executeUpdate("INSERT INTO PUBLIC.rr_award_cycle(id,agency_id,code,normalized_code,title,policy_version_id,policy_definition_version,policy_fingerprint,nomination_opens_on,nomination_closes_on,evaluation_opens_on,evaluation_closes_on,decision_due_on,status,record_version,created_by,created_at,updated_by,updated_at) VALUES('cycle','A','2026','2026','2026 PRAISE','policy-v1',1,'fp',DATE '2026-01-01',DATE '2026-01-31',DATE '2026-01-31',DATE '2026-02-28',DATE '2026-03-15','CLOSED',0,'test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");}Flyway upgraded=flyway(url,p,"45");upgraded.migrate();assertThat(upgraded.info().current().getVersion().getVersion()).isEqualTo("45");try(var c=DriverManager.getConnection(url,"sa","");var r=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.rr_award_cycle WHERE id='cycle'")){r.next();assertThat(r.getLong(1)).isOne();}try(var c=DriverManager.getConnection(url,"sa","");var r=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.rr_evaluation_case")){r.next();assertThat(r.getLong(1)).isZero();}}finally{initial.clean();}}private Flyway flyway(String url,Map<String,String>p,String target){return Flyway.configure().dataSource(url,"sa","").locations("classpath:db/migration/postgresql").schemas("PUBLIC").defaultSchema("PUBLIC").placeholders(p).target(MigrationVersion.fromVersion(target)).cleanDisabled(false).load();}}
